import type { GameState } from '../game.ts';
import type { Tournament, TournamentMatch, TournamentPhase, TournamentPlayer, TournamentResult } from './tournament.ts';

export type TournamentPayload =
  | { readonly kind: 'setup'; readonly playerCount: 4 | 8; readonly names: readonly string[] }
  | { readonly kind: 'tournament'; readonly tournament: Tournament; readonly game: GameState | null };

export function encodeTournamentJson(
  tournament: Tournament | null,
  playerCount: 4 | 8,
  names: readonly string[],
  gameSnapshot: string,
): string {
  if (!tournament) {
    return JSON.stringify({ version: 1, type: 'setup', playerCount, names: names.slice(0, playerCount) }, null, 2);
  }
  const savedGame = tournament.phase === 'playing' ? parseJson(gameSnapshot) : null;
  return JSON.stringify({ version: 1, type: 'tournament', tournament, game: savedGame }, null, 2);
}

export function decodeTournamentJson(text: string): TournamentPayload | null {
  if (new TextEncoder().encode(text).byteLength > 65_536) return null;
  const value = parseJson(text);
  if (!isJsonObject(value) || value.version !== 1 || typeof value.type !== 'string') return null;
  if (value.type === 'setup') {
    if (!hasExactKeys(value, ['version', 'type', 'playerCount', 'names'])) return null;
    if ((value.playerCount !== 4 && value.playerCount !== 8) || !stringArray(value.names, value.playerCount)) return null;
    return { kind: 'setup', playerCount: value.playerCount, names: value.names };
  }
  if (value.type !== 'tournament' || !hasExactKeys(value, ['version', 'type', 'tournament', 'game'])) return null;
  const tournament = decodeTournament(value.tournament);
  if (!tournament) return null;
  if (value.game === null) return tournament.phase === 'playing' ? null : { kind: 'tournament', tournament, game: null };
  if (tournament.phase !== 'playing') return null;
  const game = decodeSnapshot(JSON.stringify(value.game));
  const match = tournament.matches[tournament.currentMatch];
  if (!game || !match || game.boardCode !== match.boardCode) return null;
  return { kind: 'tournament', tournament, game };
}

export function decodeTournament(value: unknown): Tournament | null {
  if (!isJsonObject(value) || !hasExactKeys(value, ['startedAt', 'players', 'matches', 'currentMatch', 'turn', 'phase', 'champion'])) return null;
  if (!isNonnegativeSafeInteger(value.startedAt) || !Array.isArray(value.players) || !Array.isArray(value.matches)) return null;
  const names: string[] = [];
  const players: TournamentPlayer[] = [];
  for (const player of value.players) {
    if (!isJsonObject(player) || !hasExactKeys(player, ['seed', 'name']) || typeof player.name !== 'string') return null;
    if (player.seed !== names.length + 1 || normalizePlayerName(player.name) !== player.name) return null;
    names.push(player.name);
    players.push({ seed: player.seed, name: player.name });
  }
  if (playerNamesError(names)) return null;
  const count = names.length;
  if (count !== 4 && count !== 8) return null;
  const codes: string[] = [];
  for (const match of value.matches) {
    if (!isJsonObject(match) || typeof match.boardCode !== 'string') return null;
    codes.push(match.boardCode);
  }
  const initial = createTournament(names, codes, value.startedAt);
  if (!initial || value.matches.length !== initial.matches.length) return null;
  const matches: TournamentMatch[] = [];
  for (let index = 0; index < value.matches.length; index += 1) {
    const match = readMatch(value.matches[index], initial.matches[index]);
    if (!match) return null;
    matches.push(match);
  }
  if (!advancementIsValid(matches, count)) return null;
  if (!isNonnegativeSafeInteger(value.currentMatch) || value.currentMatch >= matches.length) return null;
  if (value.turn !== 0 && value.turn !== 1) return null;
  const phase = readPhase(value.phase);
  if (!phase) return null;
  if (value.champion !== null && !isNonnegativeSafeInteger(value.champion)) return null;
  const tournament: Tournament = {
    startedAt: value.startedAt,
    players,
    matches,
    currentMatch: value.currentMatch,
    turn: value.turn,
    phase,
    champion: value.champion,
  };
  return phaseIsValid(tournament) ? tournament : null;
}

function stringArray(value: unknown, length: number): value is string[] {
  return Array.isArray(value) && value.length === length && value.every((item) => typeof item === 'string');
}

function readMatch(value: unknown, expected: TournamentMatch | undefined): TournamentMatch | null {
  if (!expected || !isJsonObject(value) || !hasExactKeys(value, ['round', 'stage', 'boardCode', 'players', 'results', 'winner'])) return null;
  if (value.round !== expected.round || value.stage !== expected.stage || typeof value.boardCode !== 'string' || value.boardCode !== expected.boardCode || !parseBoardCode(value.boardCode)) return null;
  if (!twoValues(value.players) || !twoValues(value.results)) return null;
  const playerValues = value.players;
  const firstSeed = playerValues[0];
  const secondSeed = playerValues[1];
  if (!isTournamentSeed(firstSeed) || !isTournamentSeed(secondSeed)) return null;
  if (expected.round === 1 && (firstSeed !== expected.players[0] || secondSeed !== expected.players[1])) return null;
  const firstResult = readResult(value.results[0]);
  const secondResult = readResult(value.results[1]);
  if (firstResult === undefined || secondResult === undefined) return null;
  if ((firstSeed === null) !== (firstResult === null) || (secondSeed === null) !== (secondResult === null)) return null;
  if ((firstResult && firstResult.seed !== firstSeed) || (secondResult && secondResult.seed !== secondSeed)) return null;
  const players: readonly [number | null, number | null] = [firstSeed, secondSeed];
  const results: readonly [TournamentResult | null, TournamentResult | null] = [firstResult, secondResult];
  const expectedWinner = firstResult && secondResult
    ? compareResults(firstResult, secondResult)
    : null;
  if (value.winner !== expectedWinner) return null;
  return { round: expected.round, stage: expected.stage, boardCode: expected.boardCode, players, results, winner: expectedWinner };
}

function twoValues(value: unknown): value is [unknown, unknown] {
  return Array.isArray(value) && value.length === 2;
}

function isTournamentSeed(value: unknown): value is number | null {
  return value === null || (isNonnegativeSafeInteger(value) && value >= 1 && value <= 8);
}

function readResult(value: unknown): TournamentResult | null | undefined {
  if (value === null) return null;
  if (!isJsonObject(value) || !hasExactKeys(value, ['seed', 'moves', 'elapsedMs'])) return undefined;
  if (!isNonnegativeSafeInteger(value.seed) || value.seed < 1 || value.seed > 8) return undefined;
  if (!isNonnegativeSafeInteger(value.moves) || value.moves > MOVES_MAX || typeof value.elapsedMs !== 'number' || !Number.isFinite(value.elapsedMs) || value.elapsedMs < 0 || value.elapsedMs > ELAPSED_MAX_MS) return undefined;
  return { seed: value.seed, moves: value.moves, elapsedMs: value.elapsedMs };
}

function compareResults(first: TournamentResult, second: TournamentResult): number {
  if (first.moves !== second.moves) return first.moves < second.moves ? first.seed : second.seed;
  if (first.elapsedMs !== second.elapsedMs) return first.elapsedMs < second.elapsedMs ? first.seed : second.seed;
  return Math.min(first.seed, second.seed);
}

function advancementIsValid(matches: readonly TournamentMatch[], count: number): boolean {
  for (const match of matches) {
    if (match.round === 1) continue;
    const priorStart = matches.findIndex((item) => item.round === match.round - 1);
    const priorRound = matches.filter((item) => item.round === match.round - 1);
    const nextRound = matches.filter((item) => item.round === match.round);
    const matchIndex = nextRound.indexOf(match);
    const first = priorRound[matchIndex * 2]?.winner ?? null;
    const second = priorRound[matchIndex * 2 + 1]?.winner ?? null;
    const shouldAdvance = priorRound.length > 0 && priorRound.every((item) => item.winner !== null);
    if (shouldAdvance ? match.players[0] !== first || match.players[1] !== second : match.players[0] !== null || match.players[1] !== null) return false;
    if (priorStart < 0 || matchIndex < 0) return false;
  }
  return matches.length === (count === 4 ? 3 : 7);
}

function phaseIsValid(tournament: Tournament): boolean {
  const match = tournament.matches[tournament.currentMatch];
  if (!match) return false;
  const sameRound = tournament.matches.map((item, index) => ({ item, index })).filter(({ item }) => item.round === match.round);
  if (sameRound.some(({ item, index }) => index < tournament.currentMatch && item.winner === null)) return false;
  if (sameRound.some(({ item, index }) => index > tournament.currentMatch && item.winner !== null)) return false;
  const first = match.results[0];
  const second = match.results[1];
  if (tournament.phase === 'ready' || tournament.phase === 'playing') {
    return match.winner === null && (tournament.turn === 0 ? first === null && second === null : first !== null && second === null) && match.players[tournament.turn] !== null && tournament.champion === null;
  }
  if (tournament.phase === 'turn-finished') return tournament.turn === 0 && first !== null && second === null && tournament.champion === null;
  if (tournament.phase === 'match-finished') return match.winner !== null && first !== null && second !== null && tournament.champion === null;
  return match.stage === 'Final' && match.winner !== null && tournament.champion === match.winner &&
    tournament.matches.every((item) => item.winner !== null);
}

function readPhase(value: unknown): TournamentPhase | null {
  if (value === 'ready' || value === 'playing' || value === 'turn-finished' || value === 'match-finished' || value === 'finished') return value;
  return null;
}
import { useRef, useState } from 'react';
import { freshBoardCodes } from '../session/fresh-board.ts';
import { browserStore } from '../session/use-saved-preferences.ts';
import {
  activeTournamentMatch,
  beginTournamentTurn,
  createTournament,
  nextTournamentMatch,
  nextTournamentTurn,
  normalizePlayerName,
  playerNamesError,
  recordTournamentResult,
  tournamentBoardSizes,
} from './tournament.ts';
import { decodeTournamentJson, encodeTournamentJson } from './tournament-format.ts';
import { readTournamentHistory, writeTournamentHistory } from './tournament-storage.ts';
import type { GameState } from '../game.ts';
import type { Tournament, TournamentMatch } from './tournament.ts';

export function useTournament() {
  const [store] = useState(browserStore);
  const [historyRead] = useState(() => readTournamentHistory(store));
  const [playerCount, setPlayerCount] = useState<4 | 8>(4);
  const [names, setNames] = useState<string[]>(() => Array<string>(8).fill(''));
  const [tournament, setTournament] = useState<Tournament | null>(null);
  const [past, setPast] = useState(historyRead.tournaments);
  const pastRef = useRef(past);
  const [json, setJson] = useState('');
  const [notice, setNotice] = useState('');
  const [storageNotice, setStorageNotice] = useState(
    historyRead.available ? '' : "Progress won't be saved on this device.",
  );

  function editName(index: number, value: string): void {
    setNames((current) => current.map((name, position) => position === index ? value : name));
  }

  function startTournament(): void {
    const acceptedNames = names.slice(0, playerCount).map(normalizePlayerName);
    const error = playerNamesError(acceptedNames);
    if (error) {
      setNotice(error);
      return;
    }
    const codes = freshBoardCodes(tournamentBoardSizes(playerCount));
    const startedAt = Math.max(Date.now(), (pastRef.current[0]?.startedAt ?? 0) + 1);
    const next = createTournament(acceptedNames, codes, startedAt);
    if (!next) {
      setNotice('Unable to start tournament.');
      return;
    }
    setTournament(next);
    setNotice('');
  }

  function startTurn(): TournamentMatch | undefined {
    if (!tournament || tournament.phase !== 'ready') return undefined;
    const match = activeTournamentMatch(tournament);
    setTournament(beginTournamentTurn(tournament));
    return match;
  }

  function finishTurn(game: GameState): void {
    setTournament((current) => current ? recordTournamentResult(current, game.moves, game.elapsedMs) : current);
  }

  function nextTurn(): void {
    setTournament((current) => current ? nextTournamentTurn(current) : current);
  }

  function nextMatch(): void {
    if (!tournament) return;
    const next = nextTournamentMatch(tournament);
    setTournament(next);
    if (next.phase === 'finished') remember(next);
  }

  function remember(finished: Tournament): void {
    if (pastRef.current.some((item) => item.startedAt === finished.startedAt)) return;
    const next = [finished, ...pastRef.current].slice(0, 10);
    pastRef.current = next;
    setPast(next);
    setStorageNotice(writeTournamentHistory(store, next) ? '' : "Progress won't be saved on this device.");
  }

  function exportJson(gameSnapshot: string): void {
    setJson(encodeTournamentJson(tournament, playerCount, names, gameSnapshot));
    setNotice('');
  }

  function loadJson(): { readonly kind: 'setup' } | { readonly kind: 'tournament'; readonly game: GameState | null } | null {
    const payload = decodeTournamentJson(json);
    if (!payload) {
      setNotice('Invalid tournament.');
      return null;
    }
    setNotice('');
    if (payload.kind === 'setup') {
      setPlayerCount(payload.playerCount);
      setNames([...payload.names, ...Array<string>(8 - payload.names.length).fill('')]);
      setTournament(null);
      return { kind: 'setup' };
    }
    setTournament(payload.tournament);
    if (payload.tournament.phase === 'finished') remember(payload.tournament);
    return { kind: 'tournament', game: payload.game };
  }

  function leaveTournament(): void {
    setTournament(null);
    setNotice('');
  }

  return {
    playerCount,
    setPlayerCount: (value: number) => setPlayerCount(value === 8 ? 8 : 4),
    names,
    editName,
    tournament,
    past,
    json,
    setJson,
    notice,
    storageNotice,
    startTournament,
    startTurn,
    finishTurn,
    nextTurn,
    nextMatch,
    exportJson,
    loadJson,
    leaveTournament,
  };
}

# Open Forge Loader

Agents read this file before every task. It says what to read, how to use it, and how to change what agents use.

The list under `Entries` at the bottom is the whole setup: the folders of rules and notes, and any other documents, that agents use in this workspace. Anything not listed is only background reading. Your project's own requirements, and the instructions your agent tool already loads, still apply. Everything works with plain files, and the CLI only makes it faster.

## Axioms

### Read before you work

1. **List your working files.** Do this when a task starts or resumes, and again after your context is restored. Working files are the files you will investigate, review, create, change, rename or delete, including planned files and both paths of a rename. A file you only read for background is not a working file.
2. **Use the CLI if you can.** If the `open-forge` CLI is available and allowed, run `open-forge context` with `--for <file>` once for each working file, and read its output. It covers steps 3 and 4. You still do step 5 yourself. If the command is missing, fails or cannot follow a link, do steps 3 to 5 with your own file tools.
3. **Check conditions first.** Some entries end with `applies to` and one or more patterns. Such an entry applies only when one of your working files matches it, and that same file also matches every conditioned catalogue above it. Within one list, any pattern may match. Patterns are case-sensitive globs from the workspace root: `*.py` matches root files, `**/*.py` matches any depth, and `docs/**` matches a folder's contents. A leading `!` is literal, not an exclusion. Conditions never open a branch on their own and never grant edit permission. If you don't know your working files yet, report conditioned required entries as pending, and resolve them before you touch a matching file.
4. **Read what is required.** Read every applicable entry tagged #LoadNow or #KeepInMind, in the order listed. A catalogue is a file that lists a folder's context under its own `Entries`. When you read one, repeat steps 3 and 4 for its Entries. Never skip a required read because its description looks unrelated. Read each file once per pass.
5. **Open what fits the task.** Check the descriptions of the other listed entries and open the ones that fit. Follow any link that a file you read says to read. If search or a direct link leads you to a listed file, read the catalogues above it before you apply it. Keep separately selected branches separate. Use catalogues to find things, and don't open ordinary files just to discover more links or tags.

Start again from step 1 when your goal or working files change. Before you hand off or finish, reread the #KeepInMind entries in the branches you are using. During work, reread them only when they may have changed.

### Use what you read

- **Rules.** Follow the `## Axioms` of every catalogue you load and the `## Instructions` of every rule file, within the scope each one states. Only this loader and loaded catalogues define Axioms. A narrower rule adds to a broader one and never outranks it. If two rules conflict, or you cannot follow one, say so and explain why.
- **The user.** Follow the user's direction within platform and safety limits. Take routine, reversible steps inside the request without asking again, and state the assumptions that affect the result. Ask first when an open choice could significantly change the result, scope, risk, cost, external effects or the ability to undo the work.
- **Answers.** Match explanation and planning to the request. Unless the user asks for deeper analysis, start with your current understanding, one recommendation and at most one important open choice.
- **Words.** In replies and in what you write, use the fewest words that keep the meaning, readability and logical order. Cut filler and repetition, but keep the context, conditions and exceptions a reader needs to apply the result.
- **What counts as accepted.** Reading, linking, saving or tagging something does not make it accepted, and does not give you permission to edit it. Content is accepted when the user agrees, or when a source the user named for that question says so. Use declared external authorities for the facts they own. #Contextual marks content that is not accepted, and #CurrentTruth marks accepted current state within its scope. Tags, repetition and your own confidence never make something accepted. Evidence can support a claim without making it accepted.
- **One question per source.** Let each source answer one clear question, and link to related sources instead of repeating their detail. A link never changes either source's authority, scope, loading or lifecycle. Selected advice or other non-binding material may specialize broader material of the same kind within its accepted scope.
- **Conflicts and change.** When two accepted sources disagree, investigate before you edit either. When accepted direction changes the current state, update the source that defines it and keep useful prior context.
- **#Evergreen.** This tag marks material that must stay in step with accepted current state. It grants no authority and loads nothing. Update affected #Evergreen sources you may edit before other work depends on them, and by closeout at the latest. Batch related updates when that is safe.
- **Staying current.** Keep each source true to what it represents now. Keep useful prior context in a listed Memory route or another existing source. Report updates you could not make or were not allowed to make.

### Change what agents use

- **Add something.** Add a line under `Entries` with a path relative to this file, such as `../docs/architecture.md` or `../.cursor/rules/testing.mdc`. The line carries the description, tags and conditions, so the document needs no frontmatter and stays where it is. A linked Markdown catalogue, such as `../docs/_docs.md`, brings its Entries along. With the CLI, `open-forge route include <file>` writes the line for you.
- **Remove something.** Remove its line. Its files stay as plain notes, and reading them for background does not bring their rules back. Removing a line does not cancel accepted project requirements or the instructions your agent tool loads on its own. A removed line stays removed until the user asks to restore it.
- **Check what depends on it.** Before you remove a line, remove or replace the listed parts that need it, and report anything you cannot resolve. Inside other catalogues, the list follows the files in that folder, so move or delete a file to keep it out. When the CLI manages updates, also record the removal in its exclusions before you update.
- **Missing files.** Report a listed file or required dependency that is missing as an error. An empty `Entries` list is valid.
- **Required reads.** #LoadNow means a file is read whenever its parent loads. #KeepInMind adds the rereads described above. Both act only through catalogues you have read, so neither opens a branch nobody selected. Keep a required file's catalogue chain unbroken. Add these tags only when the read is really needed, and narrow specialized content before you make it required. No other tag changes loading.
- **Writing context.** Before you author workspace context, catalogues or metadata, read the file formats under "Writing workspace files" in `README.md`. If that page was deleted, `open-forge help concepts` prints the same section. Without either, copy the shape of a neighbouring file. New routed files carry `description`, `tags` and optional `applyTo`. A native `SKILL.md` keeps its own metadata.
- **Changes that survive updates.** Put your change in `{name}.overwrite.md` next to the shipped file. It is read right after its base, with the same role, scope and loading conditions. It wins only where the two say different things about the same content, and it is not listed or selected on its own.

