    codes.push(match.boardCode);
  }
  const initial = createTournament(names, codes, value.startedAt);
  if (!initial || value.matches.length !== initial.matches.length) return null;
  const matches: TournamentMatch[] = [];
  for (let index = 0; index < value.matches.length; index += 1) {
    const match = readMatch(value.matches[index], initial.matches[index]);
    if (!match) return null;
    matches.push(match);
  }
  if (!advancementIsValid(matches, count)) return null;
  if (!isNonnegativeSafeInteger(value.currentMatch) || value.currentMatch >= matches.length) return null;
  if (value.turn !== 0 && value.turn !== 1) return null;
  const phase = readPhase(value.phase);
  if (!phase) return null;
  if (value.champion !== null && !isNonnegativeSafeInteger(value.champion)) return null;
  const tournament: Tournament = {
    startedAt: value.startedAt,
    players,
    matches,
    currentMatch: value.currentMatch,
    turn: value.turn,
    phase,
    champion: value.champion,
  };
  return phaseIsValid(tournament) ? tournament : null;
}

function stringArray(value: unknown, length: number): value is string[] {
  return Array.isArray(value) && value.length === length && value.every((item) => typeof item === 'string');
}

function readMatch(value: unknown, expected: TournamentMatch | undefined): TournamentMatch | null {
  if (!expected || !isJsonObject(value) || !hasExactKeys(value, ['round', 'stage', 'boardCode', 'players', 'results', 'winner'])) return null;
  if (value.round !== expected.round || value.stage !== expected.stage || typeof value.boardCode !== 'string' || value.boardCode !== expected.boardCode) return null;
