  if (!isNonnegativeSafeInteger(value.moves) || value.moves < minimumMoves || value.moves > MOVES_MAX || typeof value.elapsedMs !== 'number' || !Number.isFinite(value.elapsedMs) || value.elapsedMs < 0 || value.elapsedMs > ELAPSED_MAX_MS) return undefined;
  return { seed: value.seed, moves: value.moves, elapsedMs: value.elapsedMs };
