}

import { GRID_SIZES } from '../deck.ts';
import type { RefObject } from 'react';
import { DealControl } from './control-labels.ts';
import './control.css';
import './controls.css';

interface ControlsProps {
  size: number;
  newGame(size?: number): void;
  restart(): void;
  openTournament(): void;
  tournamentButtonRef?: RefObject<HTMLButtonElement | null>;
}

export function Controls({ size, newGame, restart, openTournament, tournamentButtonRef }: ControlsProps) {
  return (
    <div className="controls">
      <div className="size-control">
        <label htmlFor="grid-size">{DealControl.size}</label>
        <select
          id="grid-size"
          className="control"
          value={size}
          onChange={(event) => newGame(Number(event.currentTarget.value))}
        >
