export type TournamentStage = 'Quarterfinal' | 'Semifinal' | 'Final';
export type TournamentPhase = 'ready' | 'playing' | 'turn-finished' | 'match-finished' | 'finished';
export interface TournamentPlayer {
  readonly seed: number;
  readonly name: string;
}
export interface TournamentResult {
  readonly seed: number;
  readonly moves: number;
  readonly elapsedMs: number;
}
export interface TournamentMatch {
  readonly round: number;
  readonly stage: TournamentStage;
  readonly boardCode: string;
  readonly players: readonly [number | null, number | null];
  readonly results: readonly [TournamentResult | null, TournamentResult | null];
  readonly winner: number | null;
}
export interface Tournament {
  readonly startedAt: number;
  readonly players: readonly TournamentPlayer[];
  readonly matches: readonly TournamentMatch[];
  readonly currentMatch: number;
  readonly turn: 0 | 1;
  readonly phase: TournamentPhase;
  readonly champion: number | null;
}

export function tournamentBoardSizes(count: number): number[] {
  return count === 4 ? [6, 6, 8] : count === 8 ? [4, 4, 4, 4, 6, 6, 8] : [];
}

export function normalizePlayerName(value: string): string {
  return value.trim().replace(/\s+/gu, ' ').normalize('NFC');
}

export function playerNamesError(names: readonly string[]): string {
  if (
    names.some((name) => {
      const length = Array.from(normalizePlayerName(name)).length;
      return length < 2 || length > 20;
    })
  )
    return 'Use 2 to 20 characters.';
  const normalized = names.map((name) => normalizePlayerName(name).toLowerCase());
  return new Set(normalized).size === normalized.length ? '' : 'Each name must be different.';
}

function openingPairings(count: number): [number, number][] {
  return count === 4
    ? [
        [1, 4],
        [2, 3],
      ]
    : [
        [1, 8],
        [4, 5],
        [3, 6],
        [2, 7],
      ];
}

export function createTournament(
  names: readonly string[],
  codes: readonly string[],
  startedAt: number,
): Tournament | null {
  if (
    (names.length !== 4 && names.length !== 8) ||
    codes.length !== tournamentBoardSizes(names.length).length ||
    !Number.isSafeInteger(startedAt) ||
    startedAt < 0
  )
    return null;
  const sizes = tournamentBoardSizes(names.length);
  if (codes.some((code, index) => parseBoardCode(code)?.size !== sizes[index])) return null;
  if (new Set(codes).size !== codes.length || playerNamesError(names)) return null;
  const players = names.map((raw, index) => ({ seed: index + 1, name: normalizePlayerName(raw) }));
  const pairings = openingPairings(names.length);
  const rounds = names.length === 4 ? [2, 1] : [4, 2, 1];
  let codeIndex = 0;
  const matches = rounds.flatMap((count, roundIndex) =>
    Array.from({ length: count }, (_, matchIndex): TournamentMatch => {
      const round = roundIndex + 1;
      const firstRound = round === 1 ? pairings[matchIndex] : undefined;
      const boardCode = codes[codeIndex++];
      if (!boardCode) throw new Error('Missing tournament deal.');
      return {
        round,
        stage:
          names.length === 8 && round === 1
            ? 'Quarterfinal'
            : round === (names.length === 4 ? 1 : 2)
              ? 'Semifinal'
              : 'Final',
        boardCode,
        players: [firstRound?.[0] ?? null, firstRound?.[1] ?? null],
        results: [null, null],
        winner: null,
      };
    }),
  );
  return {
    startedAt,
    players,
    matches,
    currentMatch: 0,
    turn: 0,
    phase: 'ready',
    champion: null,
  };
}

export function tournamentPlayer(
  tournament: Tournament,
  seed: number | null,
): TournamentPlayer | undefined {
  return seed === null ? undefined : tournament.players[seed - 1];
}

export function activeTournamentMatch(tournament: Tournament): TournamentMatch | undefined {
  return tournament.matches[tournament.currentMatch];
}

export function beginTournamentTurn(tournament: Tournament): Tournament {
  return tournament.phase === 'ready' ? { ...tournament, phase: 'playing' } : tournament;
}

export function nextTournamentTurn(tournament: Tournament): Tournament {
  return tournament.phase === 'turn-finished'
    ? { ...tournament, turn: 1, phase: 'ready' }
    : tournament;
}

export function recordTournamentResult(
  tournament: Tournament,
  moves: number,
  elapsedMs: number,
): Tournament {
  const match = activeTournamentMatch(tournament);
  const seed = match?.players[tournament.turn];
  if (
    tournament.phase !== 'playing' ||
    !match ||
    seed === null ||
    seed === undefined ||
    !Number.isSafeInteger(moves) ||
    moves < 0 ||
    moves > MOVES_MAX ||
    !Number.isFinite(elapsedMs) ||
    elapsedMs < 0 ||
    elapsedMs > ELAPSED_MAX_MS
  )
    return tournament;
  const result: TournamentResult = { seed, moves, elapsedMs };
  const results: readonly [TournamentResult | null, TournamentResult | null] =
    tournament.turn === 0 ? [result, match.results[1]] : [match.results[0], result];
  if (tournament.turn === 0) {
    return replaceCurrentMatch(tournament, { ...match, results }, 'turn-finished');
  }
  const first = results[0];
  const second = results[1];
  if (!first || !second) return tournament;
  const winner =
    first.moves !== second.moves
      ? first.moves < second.moves
        ? first.seed
        : second.seed
      : first.elapsedMs !== second.elapsedMs
        ? first.elapsedMs < second.elapsedMs
          ? first.seed
          : second.seed
        : Math.min(first.seed, second.seed);
  return replaceCurrentMatch(tournament, { ...match, results, winner }, 'match-finished');
}

function replaceCurrentMatch(
  tournament: Tournament,
  match: TournamentMatch,
  phase: TournamentPhase,
): Tournament {
  return {
    ...tournament,
    phase,
    matches: tournament.matches.map((item, index) =>
      index === tournament.currentMatch ? match : item,
    ),
  };
}

export function nextTournamentMatch(tournament: Tournament): Tournament {
  if (tournament.phase !== 'match-finished') return tournament;
  const current = activeTournamentMatch(tournament);
  if (!current || current.winner === null) return tournament;
  const pending = tournament.matches.findIndex(
    (match, index) =>
      index > tournament.currentMatch &&
      match.round === current.round &&
      match.winner === null &&
      match.players[0] !== null &&
      match.players[1] !== null,
  );
  if (pending >= 0) return { ...tournament, currentMatch: pending, turn: 0, phase: 'ready' };
  const roundMatches = tournament.matches.filter((match) => match.round === current.round);
  if (!roundMatches.every((match) => match.winner !== null)) return tournament;
  const nextRound = tournament.matches.filter((match) => match.round === current.round + 1);
  if (nextRound.length === 0) return { ...tournament, phase: 'finished', champion: current.winner };
  const previousStart = tournament.matches.findIndex((match) => match.round === current.round);
  const matches = tournament.matches.map((match) => {
    if (match.round !== current.round + 1) return match;
    const matchInRound = nextRound.indexOf(match);
    const firstIndex = previousStart + matchInRound * 2;
    const first = tournament.matches[firstIndex]?.winner ?? null;
    const second = tournament.matches[firstIndex + 1]?.winner ?? null;
    return { ...match, players: [first, second] as const };
  });
  const nextIndex = matches.findIndex((match) => match.round === current.round + 1);
  return { ...tournament, matches, currentMatch: nextIndex, turn: 0, phase: 'ready' };
}
import { decodeSnapshot } from '../snapshot.ts';
import { parseBoardCode } from '../deck.ts';
import { ELAPSED_MAX_MS, MOVES_MAX } from '../game.ts';
import {
  isJsonObject,
  hasExactKeys,
  isNonnegativeSafeInteger,
  parseJson,
} from '../saved-format.ts';
import { createTournament, normalizePlayerName, playerNamesError } from './tournament.ts';
import type { GameState } from '../game.ts';
import type {
  Tournament,
  TournamentMatch,
  TournamentPhase,
  TournamentPlayer,
  TournamentResult,
} from './tournament.ts';

export type TournamentPayload =
  | { readonly kind: 'setup'; readonly playerCount: 4 | 8; readonly names: readonly string[] }
  | {
      readonly kind: 'tournament';
      readonly tournament: Tournament;
      readonly game: GameState | null;
    };

export function encodeTournamentJson(
  tournament: Tournament | null,
  playerCount: 4 | 8,
  names: readonly string[],
  gameSnapshot: string,
): string {
  if (!tournament) {
    return JSON.stringify(
      { version: 1, type: 'setup', playerCount, names: names.slice(0, playerCount) },
      null,
      2,
    );
  }
  const savedGame = tournament.phase === 'playing' ? parseJson(gameSnapshot) : null;
  return JSON.stringify({ version: 1, type: 'tournament', tournament, game: savedGame }, null, 2);
}

export function decodeTournamentJson(text: string): TournamentPayload | null {
  if (new TextEncoder().encode(text).byteLength > 65_536) return null;
  const value = parseJson(text);
  if (!isJsonObject(value) || value.version !== 1 || typeof value.type !== 'string') return null;
  if (value.type === 'setup') {
    if (!hasExactKeys(value, ['version', 'type', 'playerCount', 'names'])) return null;
    if (
      (value.playerCount !== 4 && value.playerCount !== 8) ||
      !stringArray(value.names, value.playerCount)
    )
      return null;
    return { kind: 'setup', playerCount: value.playerCount, names: value.names };
  }
  if (
    value.type !== 'tournament' ||
    !hasExactKeys(value, ['version', 'type', 'tournament', 'game'])
  )
    return null;
  const tournament = decodeTournament(value.tournament);
  if (!tournament) return null;
  if (value.game === null)
    return tournament.phase === 'playing' ? null : { kind: 'tournament', tournament, game: null };
  if (tournament.phase !== 'playing') return null;
  const game = decodeSnapshot(JSON.stringify(value.game));
  const match = tournament.matches[tournament.currentMatch];
  if (!game || !match || game.boardCode !== match.boardCode) return null;
  return { kind: 'tournament', tournament, game };
}

export function decodeTournament(value: unknown): Tournament | null {
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, [
      'startedAt',
      'players',
      'matches',
      'currentMatch',
      'turn',
      'phase',
      'champion',
    ])
  )
    return null;
  if (
    !isNonnegativeSafeInteger(value.startedAt) ||
    !Array.isArray(value.players) ||
    !Array.isArray(value.matches)
  )
    return null;
  const names: string[] = [];
  const players: TournamentPlayer[] = [];
  for (const player of value.players) {
    if (
      !isJsonObject(player) ||
      !hasExactKeys(player, ['seed', 'name']) ||
      typeof player.name !== 'string'
    )
      return null;
    if (player.seed !== names.length + 1 || normalizePlayerName(player.name) !== player.name)
      return null;
    names.push(player.name);
    players.push({ seed: player.seed, name: player.name });
  }
  if (playerNamesError(names)) return null;
  const count = names.length;
  if (count !== 4 && count !== 8) return null;
  const codes: string[] = [];
  for (const match of value.matches) {
    if (!isJsonObject(match) || typeof match.boardCode !== 'string') return null;
    codes.push(match.boardCode);
  }
  const initial = createTournament(names, codes, value.startedAt);
  if (!initial || value.matches.length !== initial.matches.length) return null;
  const matches: TournamentMatch[] = [];
  for (let index = 0; index < value.matches.length; index += 1) {
    const match = readMatch(value.matches[index], initial.matches[index]);
    if (!match) return null;
    matches.push(match);
  }
  if (!advancementIsValid(matches, count)) return null;
  if (!isNonnegativeSafeInteger(value.currentMatch) || value.currentMatch >= matches.length)
    return null;
  if (value.turn !== 0 && value.turn !== 1) return null;
  const phase = readPhase(value.phase);
  if (!phase) return null;
  if (value.champion !== null && !isNonnegativeSafeInteger(value.champion)) return null;
  const tournament: Tournament = {
    startedAt: value.startedAt,
    players,
    matches,
    currentMatch: value.currentMatch,
    turn: value.turn,
    phase,
    champion: value.champion,
  };
  return phaseIsValid(tournament) ? tournament : null;
}

function stringArray(value: unknown, length: number): value is string[] {
  return (
    Array.isArray(value) &&
    value.length === length &&
    value.every((item) => typeof item === 'string')
  );
}

function readMatch(value: unknown, expected: TournamentMatch | undefined): TournamentMatch | null {
  if (
    !expected ||
    !isJsonObject(value) ||
    !hasExactKeys(value, ['round', 'stage', 'boardCode', 'players', 'results', 'winner'])
  )
    return null;
  if (
    value.round !== expected.round ||
    value.stage !== expected.stage ||
    typeof value.boardCode !== 'string' ||
    value.boardCode !== expected.boardCode
  )
    return null;
  const parsedCode = parseBoardCode(value.boardCode);
  if (!parsedCode) return null;
  if (!twoValues(value.players) || !twoValues(value.results)) return null;
  const playerValues = value.players;
  const firstSeed = playerValues[0];
  const secondSeed = playerValues[1];
  if (!isTournamentSeed(firstSeed) || !isTournamentSeed(secondSeed)) return null;
  if (
    expected.round === 1 &&
    (firstSeed !== expected.players[0] || secondSeed !== expected.players[1])
  )
    return null;
  const minimumMoves = parsedCode.size ** 2 / 2;
  const firstResult = readResult(value.results[0], minimumMoves);
  const secondResult = readResult(value.results[1], minimumMoves);
  if (firstResult === undefined || secondResult === undefined) return null;
  if (
    (firstSeed === null && firstResult !== null) ||
    (secondSeed === null && secondResult !== null)
  )
    return null;
  if (
    (firstResult && firstResult.seed !== firstSeed) ||
    (secondResult && secondResult.seed !== secondSeed)
  )
    return null;
  const players: readonly [number | null, number | null] = [firstSeed, secondSeed];
  const results: readonly [TournamentResult | null, TournamentResult | null] = [
    firstResult,
    secondResult,
  ];
  const expectedWinner =
    firstResult && secondResult ? compareResults(firstResult, secondResult) : null;
  if (value.winner !== expectedWinner) return null;
  return {
    round: expected.round,
    stage: expected.stage,
    boardCode: expected.boardCode,
    players,
    results,
    winner: expectedWinner,
  };
}

function twoValues(value: unknown): value is [unknown, unknown] {
  return Array.isArray(value) && value.length === 2;
}

function isTournamentSeed(value: unknown): value is number | null {
  return value === null || (isNonnegativeSafeInteger(value) && value >= 1 && value <= 8);
}

function readResult(value: unknown, minimumMoves: number): TournamentResult | null | undefined {
  if (value === null) return null;
  if (!isJsonObject(value) || !hasExactKeys(value, ['seed', 'moves', 'elapsedMs']))
    return undefined;
  if (!isNonnegativeSafeInteger(value.seed) || value.seed < 1 || value.seed > 8) return undefined;
  if (
    !isNonnegativeSafeInteger(value.moves) ||
    value.moves < minimumMoves ||
    value.moves > MOVES_MAX ||
    typeof value.elapsedMs !== 'number' ||
    !Number.isFinite(value.elapsedMs) ||
    value.elapsedMs < 0 ||
    value.elapsedMs > ELAPSED_MAX_MS
  )
    return undefined;
  return { seed: value.seed, moves: value.moves, elapsedMs: value.elapsedMs };
}

function compareResults(first: TournamentResult, second: TournamentResult): number {
  if (first.moves !== second.moves) return first.moves < second.moves ? first.seed : second.seed;
  if (first.elapsedMs !== second.elapsedMs)
    return first.elapsedMs < second.elapsedMs ? first.seed : second.seed;
  return Math.min(first.seed, second.seed);
}

function advancementIsValid(matches: readonly TournamentMatch[], count: number): boolean {
  if (matches.length !== (count === 4 ? 3 : 7)) return false;
  const roundCount = count === 4 ? 2 : 3;
  for (let round = 2; round <= roundCount; round += 1) {
    const priorRound = matches.filter((match) => match.round === round - 1);
    const nextRound = matches.filter((match) => match.round === round);
    if (priorRound.length !== nextRound.length * 2) return false;
    const priorComplete = priorRound.every((match) => match.winner !== null);
    const assigned = nextRound.some((match) => match.players.some((seed) => seed !== null));
    if (!priorComplete && assigned) return false;
    if (!assigned) continue;
    if (!priorComplete) return false;
    for (let index = 0; index < nextRound.length; index += 1) {
      const first = priorRound[index * 2]?.winner ?? null;
      const second = priorRound[index * 2 + 1]?.winner ?? null;
      if (nextRound[index]?.players[0] !== first || nextRound[index]?.players[1] !== second)
        return false;
    }
  }
  return true;
}

function phaseIsValid(tournament: Tournament): boolean {
  const match = tournament.matches[tournament.currentMatch];
  if (!match) return false;
  const sameRound = tournament.matches
    .map((item, index) => ({ item, index }))
    .filter(({ item }) => item.round === match.round);
  if (sameRound.some(({ item, index }) => index < tournament.currentMatch && item.winner === null))
    return false;
  if (sameRound.some(({ item, index }) => index > tournament.currentMatch && item.winner !== null))
    return false;
  const first = match.results[0];
  const second = match.results[1];
  if (tournament.phase === 'ready' || tournament.phase === 'playing') {
    return (
      match.winner === null &&
      (tournament.turn === 0
        ? first === null && second === null
        : first !== null && second === null) &&
      match.players[tournament.turn] !== null &&
      tournament.champion === null
    );
  }
  if (tournament.phase === 'turn-finished')
    return (
      tournament.turn === 0 && first !== null && second === null && tournament.champion === null
    );
  if (tournament.phase === 'match-finished')
    return (
      match.winner !== null && first !== null && second !== null && tournament.champion === null
    );
  return (
    match.stage === 'Final' &&
    match.winner !== null &&
    tournament.champion === match.winner &&
    tournament.matches.every((item) => item.winner !== null)
  );
}

function readPhase(value: unknown): TournamentPhase | null {
  if (
    value === 'ready' ||
    value === 'playing' ||
    value === 'turn-finished' ||
    value === 'match-finished' ||
    value === 'finished'
  )
    return value;
  return null;
}

import { isNonnegativeSafeInteger } from '../saved-format.ts';
import type { Tournament, TournamentMatch, TournamentPhase } from './tournament.ts';

export function isTournamentProgressValid(
  matches: readonly TournamentMatch[],
  count: number,
): boolean {
  if (matches.length !== (count === 4 ? 3 : 7)) return false;
  const roundCount = count === 4 ? 2 : 3;
  for (let round = 2; round <= roundCount; round += 1) {
    const priorRound = matches.filter((match) => match.round === round - 1);
    const nextRound = matches.filter((match) => match.round === round);
    if (priorRound.length !== nextRound.length * 2) return false;
    const priorComplete = priorRound.every((match) => match.winner !== null);
    const assigned = nextRound.some((match) => match.players.some((seed) => seed !== null));
    if (!priorComplete && assigned) return false;
    if (!assigned) continue;
    if (!priorComplete) return false;
    for (let index = 0; index < nextRound.length; index += 1) {
      const first = priorRound[index * 2]?.winner ?? null;
      const second = priorRound[index * 2 + 1]?.winner ?? null;
      if (nextRound[index]?.players[0] !== first || nextRound[index]?.players[1] !== second)
        return false;
    }
  }
  return true;
}

export function isTournamentPhaseValid(tournament: Tournament): boolean {
  const match = tournament.matches[tournament.currentMatch];
  if (!match) return false;
  const sameRound = tournament.matches
    .map((item, index) => ({ item, index }))
    .filter(({ item }) => item.round === match.round);
  if (sameRound.some(({ item, index }) => index < tournament.currentMatch && item.winner === null))
    return false;
  if (sameRound.some(({ item, index }) => index > tournament.currentMatch && item.winner !== null))
    return false;
  const first = match.results[0];
  const second = match.results[1];
  if (tournament.phase === 'ready' || tournament.phase === 'playing') {
    return (
      match.winner === null &&
      (tournament.turn === 0
        ? first === null && second === null
        : first !== null && second === null) &&
      match.players[tournament.turn] !== null &&
      tournament.champion === null
    );
  }
  if (tournament.phase === 'turn-finished')
    return (
      tournament.turn === 0 && first !== null && second === null && tournament.champion === null
    );
  if (tournament.phase === 'match-finished')
    return (
      match.winner !== null && first !== null && second !== null && tournament.champion === null
    );
  return (
    match.stage === 'Final' &&
    match.winner !== null &&
    tournament.champion === match.winner &&
    tournament.matches.every((item) => item.winner !== null)
  );
}

export function readTournamentPhase(value: unknown): TournamentPhase | null {
  if (
    value === 'ready' ||
    value === 'playing' ||
    value === 'turn-finished' ||
    value === 'match-finished' ||
    value === 'finished'
  )
    return value;
  return null;
}

export function isTournamentSeedValue(value: unknown): value is number | null {
  return value === null || (isNonnegativeSafeInteger(value) && value >= 1 && value <= 8);
}

import { useEffect, useRef } from 'react';
import type { RefObject } from 'react';
import { isWon } from '../game.ts';
import { Board } from '../board/Board.tsx';
import type { BoardFocus } from '../board/Board.tsx';
import { GameStatus } from '../status/GameStatus.tsx';
import { useGame } from '../session/use-game.ts';
import { activeTournamentMatch, tournamentPlayer } from './tournament.ts';
import { TournamentBracket } from './TournamentBracket.tsx';
import { PastTournaments } from './PastTournaments.tsx';
import { TournamentSetup } from './TournamentSetup.tsx';
import { useTournament } from './use-tournament.ts';
import './tournament.css';

export function TournamentScreen({
  onBack,
  headingRef,
}: {
  readonly onBack: () => void;
  readonly headingRef: RefObject<HTMLHeadingElement | null>;
}) {
  const controller = useGame({ savePreferences: false });
  const manager = useTournament();
  const board = useRef<BoardFocus>(null);
  const actionButton = useRef<HTMLButtonElement>(null);
  const focusReadyAction = useRef(false);
  const skipPhaseFocus = useRef(false);
  const tournament = manager.tournament;
  const { session } = controller;
  const match = tournament ? activeTournamentMatch(tournament) : undefined;
  const playerSeed =
    tournament?.phase === 'turn-finished'
      ? (match?.players[1] ?? null)
      : (match?.players[tournament?.turn ?? 0] ?? null);
  const player = tournament ? tournamentPlayer(tournament, playerSeed) : undefined;

  useEffect(() => {
    if (tournament?.phase === 'playing' && isWon(session.game)) manager.finishTurn(session.game);
  }, [session.game, tournament]);

  useEffect(() => {
    if (!tournament) return;
    if (tournament.phase === 'ready' && focusReadyAction.current) {
      focusReadyAction.current = false;
      actionButton.current?.focus();
    } else if (tournament.phase === 'turn-finished' || tournament.phase === 'match-finished') {
      if (skipPhaseFocus.current) skipPhaseFocus.current = false;
      else if (document.activeElement !== actionButton.current) actionButton.current?.focus();
    }
  }, [tournament]);

  function startTurn(): void {
    const nextMatch = manager.startTurn();
    if (nextMatch) controller.loadBoard(nextMatch.boardCode);
  }

  function loadTournament(): void {
    const loaded = manager.loadJson();
    if (loaded?.kind === 'tournament') {
      skipPhaseFocus.current =
        loaded.phase === 'turn-finished' ||
        loaded.phase === 'match-finished' ||
        (loaded.phase === 'playing' && loaded.game !== null && isWon(loaded.game));
    }
    if (loaded?.kind === 'tournament' && loaded.game) controller.restoreTournamentGame(loaded.game);
  }

  function startTournament(): void {
    if (manager.startTournament()) focusReadyAction.current = true;
  }

  function exportTournament(): void {
    manager.exportJson(controller.exportSnapshot());
  }

  function runTournamentAction(): void {
    if (!tournament || tournament.phase === 'playing') return;
    if (tournament.phase === 'ready') startTurn();
    else if (tournament.phase === 'turn-finished') manager.nextTurn();
    else if (tournament.phase === 'match-finished') manager.nextMatch();
    else onBack();
  }

  function activeTournamentView() {
    if (!tournament) return null;
    return (
      <section className="tournament-current">
        <div className="tournament-turn">
          <div
            className={
              tournament.phase === 'finished' ? 'tournament-champion' : 'tournament-turn-info'
            }
          >
            {tournament.phase === 'finished' ? (
              <h2>Champion: {tournamentPlayer(tournament, tournament.champion)?.name}</h2>
            ) : (
              <>
                {match && <p>Round: {match.stage}</p>}
                {player && tournament.phase !== 'match-finished' && (
                  <h2>Now playing: {player.name}</h2>
                )}
              </>
            )}
          </div>
          <div className="tournament-actions">
            <button
              ref={actionButton}
              type="button"
              className="control"
              aria-disabled={tournament.phase === 'playing'}
              onClick={runTournamentAction}
            >
              {tournament.phase === 'ready'
                ? 'Start turn'
                : tournament.phase === 'playing'
                  ? 'Turn in progress'
                  : tournament.phase === 'turn-finished'
                    ? 'Next turn'
                    : tournament.phase === 'match-finished'
                      ? 'Next match'
                      : 'Back to game'}
            </button>
            {tournament.phase !== 'finished' && (
              <button
                type="button"
                className="control"
                onClick={() => {
                  manager.leaveTournament();
                  onBack();
                }}
              >
                Leave tournament
              </button>
            )}
          </div>
        </div>
        {tournament.phase === 'playing' && (
          <>
            <GameStatus
              game={session.game}
              best={undefined}
              celebration={session.celebration}
              showBest={false}
            />
            <p id="tournament-board-help" className="help">
              Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space
              reveals a card.
            </p>
            <div className="game-result">
              <p role="status" aria-live="polite" aria-atomic="true">
                <span key={session.announcement}>{session.feedback}</span>
              </p>
            </div>
            <Board
              key={session.generation}
              game={session.game}
              helpId="tournament-board-help"
              activate={controller.activate}
              ref={board}
            />
          </>
        )}
        <TournamentBracket tournament={tournament} />
      </section>
    );
  }

  return (
    <section className="tournament-screen" aria-labelledby="tournament-title">
      <h2 id="tournament-title" ref={headingRef} tabIndex={-1}>
        Tournament
      </h2>
      {!tournament && (
        <>
          <TournamentSetup
            playerCount={manager.playerCount}
            names={manager.names}
            setPlayerCount={manager.setPlayerCount}
            editName={manager.editName}
            startTournament={startTournament}
          />
          <button type="button" className="control tournament-back" onClick={onBack}>
            Back to game
          </button>
        </>
      )}
      {activeTournamentView()}
      {manager.notice && (
        <p className="tournament-notice" role="status">
          {manager.notice}
        </p>
      )}
      <PastTournaments tournaments={manager.past} storageNotice={manager.storageNotice} />
      <section className="tournament-transfer" aria-label="Tournament data">
        <h3>Tournament data</h3>
        <label htmlFor="tournament-json">Tournament JSON</label>
        <textarea
          id="tournament-json"
          className="control"
          value={manager.json}
          maxLength={65_536}
          rows={8}
          spellCheck={false}
          onChange={(event) => manager.setJson(event.currentTarget.value)}
        />
        <div className="tournament-actions">
          <button type="button" className="control" onClick={exportTournament}>
            Export tournament
          </button>
          <button type="button" className="control" onClick={loadTournament}>
            Load tournament
          </button>
        </div>
      </section>
    </section>
  );
}
